  // ---- subscribe for more information ---------------------------------------
  // One seam: subscribeEmail() posts to api/subscribe.js, which puts the
  // address on the list straight away and emails it a welcome with an
  // unsubscribe link (single opt-in since 6 Oct 2026). It resolves on success
  // with the server's answer ({ status: "subscribed" } or "already") and
  // throws on anything else; the panel below renders the pending, success and
  // failure states around it.
  async function subscribeEmail(details) {
    const res = await fetch("https://launch-development-test.vercel.app/api/subscribe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...details, page: location.href })
    });
    const body = await res.json().catch(() => null);
    if (!res.ok || !body || !body.ok) throw new Error("HTTP " + res.status);
    return body;
  }

