  subForm.addEventListener("submit", async e => {
    e.preventDefault();
    if (subBusy) return;
    const first = subFirst.value.trim(), last = subLast.value.trim();
    const email = subMail.value.trim(), org = subOrg.value.trim();
    [subFirst, subLast, subMail].forEach(i => i.removeAttribute("aria-invalid"));
    // The same checks the server runs: both names, and an address that looks
    // like one. The organisation is optional.
    const missing = [subFirst, subLast].filter(i => !i.value.trim());
    if (missing.length) {
      missing.forEach(i => i.setAttribute("aria-invalid", "true"));
      subSay("Please enter your first and last name.", "bad");
      missing[0].focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
      subMail.setAttribute("aria-invalid", "true");
      subSay("Please enter an email address we can reach you at.", "bad");
      subMail.focus();
      return;
    }
    subBusy = true;
    subGo.disabled = true;
    subGo.textContent = "Sending…";
    subSay("");
    // Says what actually happened: success shows only once the server has the
    // address on the list, and an address that was already there is told so
    // (status "already", 8 Oct 2026) rather than thanked again. On failure the
    // address stays in the field, so trying again is one click.
    try {
      const result = await subscribeEmail({ firstName: first, lastName: last, email, organisation: org });
      if (result && result.status === "already") {
        subSay("This email address is already subscribed. You'll continue to receive an email whenever the dashboard's data is updated.", "ok");
      } else {
        subSay("Thank you for subscribing. You'll receive an email whenever the dashboard's data is updated.", "ok");
      }
      subForm.reset();
    } catch (err) {
      subSay("Sorry — we could not add you just now. Please try again in a moment.", "bad");
      if (window.console && console.warn) console.warn("[LAUNCH] subscribe failed:", err);
    } finally {
      subBusy = false;
      subGo.disabled = false;
      subGo.textContent = "Notify me";
    }
  });

