// @@ en/index.html:4224
  // ---- Sources footer, from data/sources.js --------------------------------
  // Two lists: first the registers and feeds a figure on this page comes from,
  // then the one-off documents behind a single medicine. An entry with no url
  // renders as plain text — that is how PMI and manufacturer communications
  // have always appeared here, and the missing link is the point in both cases.
  // Each list is A–Z by the name shown, in the page's language (8 Oct 2026):
  // the file is A–Z in English, but the French and Portuguese copies carry
  // translated names, so its order alone would not hold there.
  (function renderSources() {
    const dataUl = document.getElementById("srclist");
    const docsUl = document.getElementById("srcdocs");
    const docsWrap = document.getElementById("srcdocs-wrap");
    if (!dataUl) return;

    const reg = window.LAUNCH_SOURCES;
    if (!reg || !Array.isArray(reg.sources)) {
      // Say so rather than leaving an empty list. A footer that quietly loses
      // its sources still looks finished, and this page's entire claim is that
      // every figure on it is traceable to one of them.
      dataUl.outerHTML = '<p class="viznote">The source list could not be loaded. Please reload the page to try again.</p>';
      console.error("[LAUNCH] data/sources.js did not load");
      if (docsWrap) docsWrap.remove();
      return;
    }

    const EXT = '<span class="ext" aria-hidden="true">↗</span>';
    const link = (url, text) =>
      `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}${EXT}</a>`;
    const li = (s) => {
      const name = s.url ? link(s.url, s.label || s.title)
                         : `<span class="srcname">${esc(s.label || s.title)}</span>`;
      const also = (s.alsoSee || []).map(a => " " + link(a.url, a.label) + ".").join("");
      // The address a fetcher reads, for developers: plain, copyable text and
      // never a link, since it often shows an error or raw data in a browser
      // (12 Oct 2026). The name above stays the link to the public page.
      const raw = s.dataUrl
        ? ` <span class="srcraw">Raw data (for developers): <code>${esc(s.dataUrl)}</code></span>` : "";
      return `<li>${name}<span>${esc(s.plain)}${also}${raw}</span></li>`;
    };

    const shown = reg.sources.filter(s => s.public)
      .sort((a, b) => (a.label || a.title).localeCompare(b.label || b.title, PAGE_LANG, { sensitivity: "base", numeric: true }));
    dataUl.innerHTML = shown.filter(s => s.group !== "document").map(li).join("");
    const docs = shown.filter(s => s.group === "document");
    if (docs.length && docsUl) {
      docsUl.innerHTML = docs.map(li).join("");
      docsWrap.hidden = false;
    }
  })();

